SELECT route_id, ROUND(AVG(distance_km / NULLIF(fuel_liters, 0)), 2) AS kilometres_per_litre
FROM trips
GROUP BY route_id;

SELECT account_id, ROUND(COUNT(*) FILTER (WHERE priority = 'urgent')::numeric / NULLIF(COUNT(*), 0), 4) AS urgent_ticket_share
FROM support_tickets
GROUP BY account_id;

SELECT ticket_id, status
FROM support_tickets
WHERE payload ->> 'channel' = 'chat';

SELECT subscription_id
FROM subscriptions
WHERE status = 'active';

SELECT DISTINCT ON (s.account_id) s.account_id, s.plan_id
FROM subscriptions AS s
ORDER BY s.account_id, s.starts_on DESC, s.subscription_id DESC;

SELECT alert_id
FROM alerts
WHERE status = 'open';

SELECT customer_id, COUNT(alert_id) FILTER (WHERE status = 'open') AS open_alert_count
FROM alerts
GROUP BY customer_id;

SELECT case_id, customer_id, opened_at, outcome, resolved_at
FROM cases
WHERE resolved_at IS NULL;
